function w({registerIndicator:M,nulls:m}){M({id:"oa-pfe",name:"PFE: Polarized Fractal Efficiency",category:"Dynamics",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:10,min:2,max:200,step:1,tooltip:"Fractal path lookback period (Hannula default: 10)."},{key:"smooth",type:"number",label:"Smooth Period",default:5,min:1,max:100,step:1,tooltip:"EMA smoothing period applied to the raw efficiency (Hannula default: 5)."}],plots:[{key:"pfe",type:"line",title:"PFE",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:50,title:"Upper Threshold",color:"#ff5252",dashed:!0},{price:-50,title:"Lower Threshold",color:"#4caf50",dashed:!0},{price:0,title:"Zero Line",color:"#787b86",dashed:!0}],calc(u,h){const o=Math.min(200,Math.max(2,Math.floor(Number(h.period)||10))),P=Math.min(100,Math.max(1,Math.floor(Number(h.smooth)||5))),r=u.length,n=new Array(r).fill(NaN);if(r===0)return{pfe:m(n)};const t=u.map(e=>e.close),l=new Array(r+1).fill(0);for(let e=0;e<r;e++){let a=0;if(e>0&&Number.isFinite(t[e])&&Number.isFinite(t[e-1])){const s=t[e]-t[e-1];a=Math.sqrt(s*s+1)}l[e+1]=l[e]+a}let i=NaN,c=1,d=!0;const b=2/(P+1),f=1-b;for(let e=0;e<r;e++){if(e<o||!Number.isFinite(t[e])||!Number.isFinite(t[e-o]))continue;const a=t[e]-t[e-o],s=Math.sqrt(a*a+o*o),y=l[e+1]-l[e-o+1];if(!(y>0))continue;const N=s/y*100,p=a>=0?N:-N;if(!Number.isFinite(i))i=p,c=f,n[e]=p;else if(i=b*p+f*i,d){c*=f;const F=1/(1-c);n[e]=Number.isFinite(F)?F*i:i,d=c>1e-10}else n[e]=i}return{pfe:m(n)}}})}export{w as default};
